# generated by mBlock5 for CyberPi
# codes make you happy
# =============================================================
#  CyberPi + AI Camera 2.0  色追従プログラム（第一段階：色のみで識別）
# =============================================================
#  ・AI Camera 2.0 の「色認識(Blob)」で赤・青の物体を検知
#  ・赤い物体 -> その物体に近づく（十分近づいたら止まる。後退はしない）
#  ・青い物体 -> その物体から目を背ける（反対方向へ旋回）
#  ・なし     -> 停止（物体を見つけるまでは停止のまま待機）
#
#  ＜事前準備（AI Camera 2.0 側）＞
#   色認識モードで色を2つ、この順番で学習させる:
#     ・1色目（色番号1） = 赤   -> RED_INDEX
#     ・2色目（色番号2） = 青   -> BLUE_INDEX
# =============================================================

import event, time, cyberpi, mbuild, mbot2

# -------------------------------------------------------------
#  学習した色の番号（AI Camera で学習させた順番に合わせる）
# -------------------------------------------------------------
RED_INDEX = 1               # 赤ボール = 1色目
BLUE_INDEX = 2              # 青ボール = 2色目

# 空間属性のセレクタ（実機で確認済み）
ATTR_X = 1                  # X座標
ATTR_WIDTH = 3             # 幅(W)

# -------------------------------------------------------------
#  調整用パラメータ（実機に合わせてキャリブレーション）
# -------------------------------------------------------------
FRAME_CENTER_X = 320       # 画面中心X（画面幅640）
X_TOLERANCE = 10          # 中心とみなす左右の許容差

TARGET_WIDTH = 180         # この幅まで近づいたら止まる(px)。画面のW値を見て調整
MIN_WIDTH = 20            # これ未満の検出はノイズ/誤検出として無視

KP_TURN = 0.04            # 左右ずれ -> 旋回量への係数
KP_DRIVE = 0.4           # 距離ずれ -> 前進速度への係数

MAX_SPEED = 80           # 前進速度の上限
SPIN_SPEED = 30          # 青のとき背を向ける旋回スピード
LOOP_INTERVAL = 0.05     # 制御周期（秒）

# 赤を追従中に見失ったときの探索（首振り）パラメータ
SEARCH_DURATION = 8.0      # 見失ったあと赤を探す時間（秒）5〜10秒程度
SEARCH_SPIN_SPEED = 30     # 探索時の首振り旋回スピード
SEARCH_SWEEP_PERIOD = 1.2  # 首振りの向きを切り替える周期（秒）

FORWARD_SIGN = 1         # 前後が逆（近づくのにバックする）なら -1 にする
DEBUG = True            # True で各色の生の X/W 値を画面に表示


def clamp(value, low, high):
    if value < low:
        return low
    if value > high:
        return high
    return value


# -------------------------------------------------------------
#  色認識モードの起動（カメラを 'Color' モードにする）
# -------------------------------------------------------------
def start_color_recognition():
    while not mbuild.ai_camera.ai_camera_func_mode_get(1) == 'Color':
        mbuild.ai_camera.ai_camera_set_func_switch(3, 1)
        time.sleep(1)
    cyberpi.audio.play_until('switch')


# -------------------------------------------------------------
#  指定した色番号の X / 幅(W) を読み取る（生の値）
#    未検出のとき X は 0 または負の値を返す（=オブジェクト無し）
# -------------------------------------------------------------
def color_x(color_index):
    return mbuild.ai_camera.ai_camera_color_spatial_attribute_get(color_index, ATTR_X, 1)


def color_w(color_index):
    return mbuild.ai_camera.ai_camera_color_spatial_attribute_get(color_index, ATTR_WIDTH, 1)


def is_detected(x, w):
    # X が 0 以下 = 未検出。さらに幅が小さすぎる検出はノイズ/誤検出として無視
    return x > 0 and w >= MIN_WIDTH


# -------------------------------------------------------------
#  赤い物体に近づく（近づいて、十分近ければ止まる。後退はしない）
# -------------------------------------------------------------
def follow_red(x, w):
    # 左右のずれ（プラス=物体が右）-> 旋回成分
    error_x = x - FRAME_CENTER_X
    if abs(error_x) <= X_TOLERANCE:
        turn = 0
    else:
        turn = KP_TURN * error_x

    # 距離: 幅が TARGET_WIDTH より小さい(=遠い)ほど前進。近ければ 0（止まる）
    drive = KP_DRIVE * (TARGET_WIDTH - w)
    drive = clamp(drive, 0, MAX_SPEED)     # 0未満にしない = 後退しない

    drive = drive * FORWARD_SIGN
    # mBot2 の前進は drive_speed(v, -v)（右モーターは符号反転）
    left_speed = clamp(drive + turn, -MAX_SPEED, MAX_SPEED)
    right_speed = clamp(turn - drive, -MAX_SPEED, MAX_SPEED)
    mbot2.drive_speed(left_speed, right_speed)


# -------------------------------------------------------------
#  青ボールからそっぽを向く
# -------------------------------------------------------------
def turn_away_from_blue(x):
    # 追従とは逆向きにその場旋回して背を向ける
    if x >= FRAME_CENTER_X:
        # ボールが右 -> 左へ回って背を向ける
        mbot2.drive_speed(-SPIN_SPEED, -SPIN_SPEED)
    else:
        # ボールが左 -> 右へ回って背を向ける
        mbot2.drive_speed(SPIN_SPEED, SPIN_SPEED)


def stop():
    mbot2.drive_speed(0, 0)


# -------------------------------------------------------------
#  赤を見失ったときの首振り探索（その場で左右に旋回して赤を探す）
#    direction: +1 / -1 で旋回の向きを切り替えて首を振る
# -------------------------------------------------------------
def search_sweep(direction):
    speed = SEARCH_SPIN_SPEED * direction
    # 同符号 = その場旋回（drive_speed(v, -v) が前進なので符号を揃えると回転）
    mbot2.drive_speed(speed, speed)


# -------------------------------------------------------------
#  メインループ
# -------------------------------------------------------------
@event.start
def on_start():
    # プログラムが起動したことを最初に表示（カメラ初期化より前）
    cyberpi.display.show_label("Start", 24, "center", index=0)
    cyberpi.led.on(0, 255, 0)
    time.sleep(1)

    # カメラを色認識モードにする（待機中も分かるように表示）
    # ここで止まったままなら、カメラが応答していない（接続/電源を確認）
    cyberpi.display.show_label("Camera init...", 16, "center", index=0)
    start_color_recognition()
    cyberpi.display.show_label("Camera OK", 16, "center", index=0)
    time.sleep(1)

    # 物体を見つけるまでは停止して待機
    stop()
    cyberpi.led.off()

    # 探索（首振り）の状態
    was_following_red = False   # 直前まで赤を追従していたか
    searching = False           # 現在 赤を首振りで探索中か
    search_start = 0            # 探索を開始した時刻
    sweep_dir = 1              # 首振りの向き（+1 / -1）
    sweep_toggle = 0           # 次に首振りの向きを変える時刻

    while True:
        # 各色の生の値を読む
        rx = color_x(RED_INDEX)
        rw = color_w(RED_INDEX)
        bx = color_x(BLUE_INDEX)
        bw = color_w(BLUE_INDEX)

        # デバッグ表示（何が検出されているか確認する）
        if DEBUG:
            cyberpi.display.show_label("R x:" + str(rx) + " w:" + str(rw), 12, "top_mid", index=0)
            cyberpi.display.show_label("B x:" + str(bx) + " w:" + str(bw), 12, "middle_mid", index=1)

        now = time.time()

        if is_detected(rx, rw):
            # 赤い物体 -> 近づく（探索中だったら解除して再追従）
            searching = False
            was_following_red = True
            cyberpi.led.on(255, 0, 0)
            follow_red(rx, rw)

        elif was_following_red:
            # 赤を追従していたのに見失った -> 首振りで赤を探す
            if not searching:
                # 探索開始
                searching = True
                search_start = now
                sweep_dir = 1
                sweep_toggle = now + SEARCH_SWEEP_PERIOD

            if now - search_start <= SEARCH_DURATION:
                # 探索中：一定周期で首振りの向きを反転しながらその場旋回
                cyberpi.led.on(255, 128, 0)   # 探索中はオレンジ
                if now >= sweep_toggle:
                    sweep_dir = -sweep_dir
                    sweep_toggle = now + SEARCH_SWEEP_PERIOD
                search_sweep(sweep_dir)
            else:
                # 時間切れ：探索をあきらめて通常動作（青/停止）へ戻す
                searching = False
                was_following_red = False
                stop()
                cyberpi.led.off()

        elif is_detected(bx, bw):
            # 青い物体 -> 目を背ける
            cyberpi.led.on(0, 0, 255)
            turn_away_from_blue(bx)

        else:
            # 何も無い -> 停止
            stop()
            cyberpi.led.off()

        time.sleep(LOOP_INTERVAL)
